diff --git a/src/transport/ws/messageHandler.test.ts b/src/transport/ws/messageHandler.test.ts
index 110f899..2e92cf7 100644
--- a/src/transport/ws/messageHandler.test.ts
+++ b/src/transport/ws/messageHandler.test.ts
@@ -78,6 +78,29 @@ describe('the websocket message handler', () => {
       expect({frames: h.frames(), streams: calls.length}).toEqual({frames: ['error INVALID_MESSAGE'], streams: 0});
     });

+    it('answers a list_sessions with the session_list while a user_message is still streaming', async () => {
+      const release = deferred();
+      const sent: OutgoingMessage[] = [];
+      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
+      const orchestrator = {
+        processMessageStream: async function* (): AsyncGenerator<MessageChunk> {
+          await release.until;
+          yield STOP;
+        },
+      } as unknown as ChatOrchestrator;
+      const store = {listFor: async () => []} as unknown as Parameters<typeof createMessageHandler>[1];
+      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
+      const handle = createMessageHandler(orchestrator, store);
+
+      const turn = handle(ws, session, {type: 'user_message', content: 'hello'});
+      await handle(ws, session, {type: 'list_sessions'});
+      const beforeRelease = wire(sent);
+      release.release();
+      await turn;
+
+      expect(beforeRelease).toEqual(['upsert 0 user "hello"', 'session_list']);
+    });
+
     it('answers a ping with the timestamp it was given', async () => {
       const h = harness([]);

diff --git a/src/transport/ws/validation.test.ts b/src/transport/ws/validation.test.ts
index e60fb80..15c4b7b 100644
--- a/src/transport/ws/validation.test.ts
+++ b/src/transport/ws/validation.test.ts
@@ -20,4 +20,31 @@ describe('the websocket frame validator', () => {

     expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
   });
+
+  it('accepts a bare list_sessions and forwards only limit and a well-formed before cursor', () => {
+    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
+    const frames = [{type: 'list_sessions'}, {type: 'list_sessions', limit: 10, before, userId: 'u2'}];
+
+    expect(frames.map(frame => validateMessage(frame))).toEqual([
+      {valid: true, data: {type: 'list_sessions'}},
+      {valid: true, data: {type: 'list_sessions', limit: 10, before}},
+    ]);
+  });
+
+  it('rejects a list_sessions with a malformed limit or before cursor', () => {
+    const good = '2026-01-01T00:00:00.000Z';
+    const bad = [
+      {limit: 'ten'},
+      {limit: -1},
+      {limit: 1.5},
+      {before: 'not-an-object'},
+      {before: null},
+      {before: {updatedAt: good, sessionId: ''}},
+      {before: {updatedAt: good, sessionId: 'a'.repeat(129)}},
+      {before: {updatedAt: 'not-a-date', sessionId: 's1'}},
+      {before: {updatedAt: true, sessionId: 's1'}},
+    ];
+
+    expect(bad.map(extra => validateMessage({type: 'list_sessions', ...extra}).valid)).toEqual(bad.map(() => false));
+  });
 });
